# ---------------- сборка ----------------
sections, key = [], ['# Ключ ответов — 7 класс (рабочая тетрадь Босовой, ч. 1, с § 1.3)\n']
for n, par, title, steps in S:
    lnum = par.replace('§ ', '')
    nums = [int(x) for st in steps for x in __import__('re').findall(r'^<p><b>(\d+)\.</b>', st['blocks'][0]['v'])]
    sections.append({'num': n, 'title': f'{par} {title}', 'lessons': [{'num': lnum, 'label': par, 'title': f'Задания {min(nums)}–{max(nums)}', 'steps': steps}]})
    key.append(f'\n## {par} {title}\n')
    for i, st in enumerate(steps, 1):
        no = __import__('re').match(r'<p><b>(\d+)\.</b>', st['blocks'][0]['v']).group(1)
        if st['type'] == 'fill': a = '; '.join(f['label'] + ' — ' + ' '.join(x.split('||')[0] for x in st['answer'][j]) for j, f in enumerate(st['fields']))
        elif st['type'] == 'choice': a = ', '.join(st['options'][k] for k in (st['answer'] if st.get('multi') else [st['answer']]))
        elif st['type'] == 'match': a = '; '.join(f'{it} → {st["options"][k]}' for it, k in zip(st['items'], st['answer']))
        else: a = 'в тетради'
        key.append(f'- шаг {i} (№ {no}): {a}\n')
course = {'id': 'inf7', 'title': '7 класс', 'sections': sections}
open(os.path.join(HERE, 'course.js'), 'w').write('/* Курс «7 класс». Собирается скриптом src/inf7/build7.py */\nwindow.COURSE = ' + json.dumps(course, ensure_ascii=False) + ';\n')
open(os.path.join(HERE, 'answers.md'), 'w').write(''.join(key))
print('разделов', len(sections), 'шагов', sum(len(s['lessons'][0]['steps']) for s in sections), 'с проверкой', sum(1 for s in sections for st in s['lessons'][0]['steps'] if st['type'] != 'text'))
